def solve():
    a, b = map(int, input().split())

    # If already equal
    if a == b:
        return 0

    # The fox can only reduce pieces that are divisible by 2, 3, or 5
    # When reducing: divisible by 2 -> becomes a/2, divisible by 3 -> becomes a/3, divisible by 5 -> becomes a/5

    # We need to find the GCD of the final values after all operations
    # Since the fox can only divide by 2, 3, or 5, the final value must be a common multiple
    # of the GCD of the original values after removing all factors of 2, 3, 5

    def remove_factors(n, factor):
        while n % factor == 0:
            n //= factor
        return n

    a_core = remove_factors(a, 2)
    a_core = remove_factors(a_core, 3)
    a_core = remove_factors(a_core, 5)

    b_core = remove_factors(b, 2)
    b_core = remove_factors(b_core, 3)
    b_core = remove_factors(b_core, 5)

    # If the cores are not equal, it's impossible
    if a_core != b_core:
        return -1

    # Now we know we can make both pieces equal to a_core
    # We need to count the number of operations needed to reduce a to a_core and b to a_core

    def count_operations(n, target):
        ops = 0
        temp = n
        while temp != target:
            if temp < target:
                return float('inf')  # impossible to reach target from above
            # Try to divide by 2, 3, or 5
            if temp % 2 == 0:
                if temp // 2 == target:
                    ops += 1
                    temp = target
                else:
                    temp //= 2
                    ops += 1
            elif temp % 3 == 0:
                if temp // 3 == target:
                    ops += 1
                    temp = target
                else:
                    temp //= 3
                    ops += 1
            elif temp % 5 == 0:
                if temp // 5 == target:
                    ops += 1
                    temp = target
                else:
                    temp //= 5
                    ops += 1
            else:
                return float('inf')
        return ops

    # We need to reduce both a and b to a_core
    # But we can only divide, not multiply

    # Count operations for a
    ops_a = 0
    temp_a = a
    while temp_a != a_core:
        if temp_a < a_core:
            return -1
        if temp_a % 2 == 0:
            temp_a //= 2
            ops_a += 1
        elif temp_a % 3 == 0:
            temp_a //= 3
            ops_a += 1
        elif temp_a % 5 == 0:
            temp_a //= 5
            ops_a += 1
        else:
            return -1

    # Count operations for b
    ops_b = 0
    temp_b = b
    while temp_b != a_core:
        if temp_b < a_core:
            return -1
        if temp_b % 2 == 0:
            temp_b //= 2
            ops_b += 1
        elif temp_b % 3 == 0:
            temp_b //= 3
            ops_b += 1
        elif temp_b % 5 == 0:
            temp_b //= 5
            ops_b += 1
        else:
            return -1

    return ops_a + ops_b

